3: import { BehaviorSubject } from 'rxjs';
4: import { environment } from '../../environments/environment.development';
5: @Injectable({
6:   providedIn: 'root',
7: })
8: export class ImplicitAuthenticationService {
9:   rolesConsulta = environment.ROLES_CONSULTA;
10:   rolesEdicion = environment.ROLES_CONSULTA_EDICION;
11:   private readonly userSubject = new BehaviorSubject({});
12:   public user$ = this.userSubject.asObservable();
13:   httpOptions: { headers: HttpHeaders } | undefined;
14: 
15:   private readonly httpClient = inject(HttpClient);
16: 
17:   constructor() {
18:     this.init();
19:     const user: any = localStorage.getItem('user');
20:     this.userSubject.next(JSON.parse(atob(user)));
21:   }
22: 
23:   init(): any {
24:     const id_token = localStorage.getItem('id_token');
25: 
26:     if (id_token) {
27:       const id_token_array = id_token.split('.');
28:       const payload = JSON.parse(atob(id_token_array[1]));
29:       this.updateAuth(payload);
30:     }
31:   }
32: 
33:   updateAuth(payload: { role: string | string[] | null }) {
34:     payload.role = this.roles2List(payload.role);
35:     this.userSubject.next({ user: payload });
36:   }
37: 
38:   roles2List(roles: string | null | string[]): string[] {
39:     if (Array.isArray(roles)) {
40:       return roles;
41:     } else if (typeof roles === 'string') {
42:       return [roles];
43:     } else {
44:       return [];
45:     }
46:   }
47: 
48:   public getRole() {
49:     return new Promise<string[]>((resolve) => {
50:       this.user$.subscribe((data: any) => {
51:         const { user, userService } = data;
52:         const roleUser = user.role === undefined ? [] : user.role;
53:         const roleUserService =
54:           userService.role === undefined ? [] : userService.role;
55:         const roles = roleUser
56:           .concat(roleUserService)
57:           .filter((data: any) => !data.includes('/'));
58:         resolve(roles);
59:       });
60:     });
61:   }
62: 
63:   public PermisoEdicion(roles: string[]): boolean {
64:     return roles.some((rol) => this.rolesEdicion.includes(rol));
65:   }
66: 
67:   public PermisoConsulta(roles: string[]): boolean {
68:     return roles.some((rol) => this.rolesConsulta.includes(rol));
69:   }
70: }

