338:   private formatFechaHora(iso: string): string {
339:     if (!iso) return '';
340:     try {
341:       // El MID retorna el formato Go: "2026-05-15 12:45:46.202365 +0000 +0000"
342:       // El valor de hora es Colombia (wall clock), sin conversión de zona.
343:       // Normalizamos a "YYYY-MM-DDTHH:mm:ss" sin TZ para que new Date()
344:       // lo trate como hora local y getHours() devuelva exactamente ese valor.
345:       const clean = iso.trim()
346:         .replace(' ', 'T')       // primer espacio → T
347:         .replace(/\.\d+.*$/, '') // quitar microsegundos y todo lo que sigue (+0000 +0000)
348:         .replace(/Z$/, '')       // quitar Z si viniera en otro formato
349:         .replace(/[+-]\d{2}:?\d{2}$/, ''); // quitar ±HH:MM o ±HHMM si quedara
350:       const d = new Date(clean);
351:       if (isNaN(d.getTime())) return iso;
352:       const dd = String(d.getDate()).padStart(2, '0');
353:       const mm = String(d.getMonth() + 1).padStart(2, '0');
354:       const yyyy = d.getFullYear();
355:       const hh = String(d.getHours()).padStart(2, '0');
356:       const min = String(d.getMinutes()).padStart(2, '0');
357:       return `${dd}/${mm}/${yyyy} ${hh}:${min}`;
358:     } catch {
359:       return iso;
360:     }
361:   }
